"use client";

import { AppShell, LoadingState } from "@/components/app-shell";
import { customQuestionError, type PrivateQuestionKey, type PrivateQuestionKeys } from "@/lib/custom-questions";
import { useDemo } from "@/lib/demo-store";
import type { ActivityConfig, Classroom, CustomQuestion } from "@/lib/types";
import { ArrowDown, ArrowUp, CirclePlus, Lightbulb, Trash2 } from "lucide-react";
import { useParams, useRouter } from "next/navigation";
import { FormEvent, useEffect, useState } from "react";

function blankQuestion(id:number):CustomQuestion{return{id,title:"",mixture:"",objective:"",equipment:[{id:"tool-1",label:""},{id:"tool-2",label:""}],maxPoints:5,correctPoints:5,wrongPenalty:1}}
function blankKey():PrivateQuestionKey{return{steps:[],hint:"",explanation:""}}

export default function QuestionsPage(){
  const{id}=useParams<{id:string}>();const store=useDemo();const room=store.rooms.find(item=>item.id===id);
  if(!store.ready||!room)return <AppShell title="สร้างโจทย์"><LoadingState/></AppShell>;
  if(!store.canManage(id))return <AppShell title="สร้างโจทย์"><main className="empty-state"><h1>ไม่มีสิทธิ์จัดการห้องนี้</h1></main></AppShell>;
  return <QuestionBuilder key={room.id} room={room} teacherToken={store.teacherToken(room.id)}/>;
}

function QuestionBuilder({room,teacherToken}:{room:Classroom;teacherToken?:string}){
  const router=useRouter();
  const existing=room.activity.mode==="QUESTIONS"&&!!room.activity.customQuestions?.length;
  const [title,setTitle]=useState(existing?room.activity.title:"ชาเลนจ์การแยกสาร");
  const [hintsEnabled,setHintsEnabled]=useState(existing?room.activity.hintsEnabled===true:true);
  const [questions,setQuestions]=useState<CustomQuestion[]>(existing?room.activity.customQuestions!:[blankQuestion(1000)]);
  const [answerKeys,setAnswerKeys]=useState<PrivateQuestionKeys>(existing?{}:{"1000":blankKey()});
  const [keysReady,setKeysReady]=useState(!existing);
  const [active,setActive]=useState(0);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState("");
  useEffect(()=>{if(!existing)return;let cancelled=false;fetch(`/api/teacher/rooms/${room.id}/questions`,{headers:teacherToken?{"x-teacher-token":teacherToken}:{}}).then(async response=>{const data=await response.json() as {answerKeys?:PrivateQuestionKeys;error?:string};if(!response.ok)throw new Error(data.error??"โหลดเฉลยไม่สำเร็จ");if(!cancelled){setAnswerKeys(data.answerKeys??{});setKeysReady(true)}}).catch(cause=>{if(!cancelled)setError(cause instanceof Error?cause.message:"โหลดเฉลยไม่สำเร็จ")});return()=>{cancelled=true}},[existing,room.id,teacherToken]);
  const question=questions[active];
  const key=answerKeys[String(question.id)]??blankKey();
  function updateQuestion(changes:Partial<CustomQuestion>){setQuestions(current=>current.map((item,index)=>index===active?{...item,...changes}:item))}
  function updateKey(changes:Partial<PrivateQuestionKey>){setAnswerKeys(current=>({...current,[question.id]:{...current[String(question.id)]??blankKey(),...changes}}))}
  function addQuestion(){if(questions.length>=10)return;const id=Math.max(999,...questions.map(item=>item.id))+1;setQuestions(current=>[...current,blankQuestion(id)]);setAnswerKeys(current=>({...current,[id]:blankKey()}));setActive(questions.length)}
  function removeQuestion(){if(questions.length<=1)return;const id=question.id;setQuestions(current=>current.filter(item=>item.id!==id));setAnswerKeys(current=>{const next={...current};delete next[String(id)];return next});setActive(Math.max(0,active-1))}
  function moveQuestion(direction:-1|1){const target=active+direction;if(target<0||target>=questions.length)return;setQuestions(current=>{const next=[...current];[next[active],next[target]]=[next[target],next[active]];return next});setActive(target)}
  function addTool(){if(question.equipment.length>=10)return;const id=`tool-${Math.max(0,...question.equipment.map(item=>Number(item.id.split("-")[1])||0))+1}`;updateQuestion({equipment:[...question.equipment,{id,label:""}]})}
  function removeTool(id:string){if(question.equipment.length<=2)return;updateQuestion({equipment:question.equipment.filter(item=>item.id!==id)});updateKey({steps:key.steps.filter(step=>step!==id)})}
  function toggleAnswer(id:string){updateKey({steps:key.steps.includes(id)?key.steps.filter(step=>step!==id):[...key.steps,id]})}
  async function save(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setError("");
    const activity:ActivityConfig={mode:"QUESTIONS",title:title.trim(),hintsEnabled,customQuestions:questions,levelIds:questions.map(item=>item.id),pointsByLevel:Object.fromEntries(questions.map(item=>[item.id,item.maxPoints]))};
    const issue=customQuestionError(activity,answerKeys);if(issue){setError(issue);return}
    setBusy(true);
    try{const response=await fetch(`/api/teacher/rooms/${room.id}/questions`,{method:"PUT",headers:{"content-type":"application/json",...(teacherToken?{"x-teacher-token":teacherToken}:{})},body:JSON.stringify({activity,answerKeys})});const data=await response.json() as {error?:string};if(!response.ok)throw new Error(data.error??"บันทึกโจทย์ไม่สำเร็จ");router.push(`/teacher/classrooms/${room.id}`)}
    catch(cause){setError(cause instanceof Error?cause.message:"บันทึกโจทย์ไม่สำเร็จ")}finally{setBusy(false)}
  }
  return <AppShell title="สร้างโจทย์" back={`/teacher/classrooms/${room.id}`}><main className="dashboard-shell question-builder"><div className="page-heading"><div><p className="eyebrow">ห้อง {room.name}</p><h1>สร้างชาเลนจ์ของครู</h1><p>ตั้งโจทย์ เลือกอุปกรณ์ จัดลำดับเฉลย และกำหนดคะแนนรายข้อ</p></div></div>{room.status!=="OPEN"?<div className="error-box" role="alert">แก้โจทย์ได้ก่อนเริ่มเกมเท่านั้น</div>:null}<form onSubmit={save} className="builder-form"><section className="panel builder-overview"><label>ชื่อเกม<input value={title} maxLength={60} onChange={event=>setTitle(event.target.value)} required/></label><label className="hint-toggle"><input type="checkbox" checked={hintsEnabled} onChange={event=>setHintsEnabled(event.target.checked)}/><Lightbulb/>เปิดคำใบ้ให้นักเรียนในเกมนี้</label><span>มี {questions.length} ข้อ · คะแนนเต็ม {questions.reduce((sum,item)=>sum+item.maxPoints,0)} คะแนน</span></section><div className="builder-layout"><aside className="panel builder-question-list"><h2>ข้อในเกม</h2>{questions.map((item,index)=><button type="button" key={item.id} className={active===index?"active":""} onClick={()=>setActive(index)}><b>ข้อ {index+1}</b><span>{item.title||"ยังไม่ตั้งชื่อ"}</span></button>)}<button type="button" className="builder-add" onClick={addQuestion} disabled={questions.length>=10}><CirclePlus/>เพิ่มข้อ</button></aside><section className="panel builder-editor"><div className="section-title"><div><h2>ข้อ {active+1}</h2><span>เฉลยจะถูกเก็บเฉพาะฝั่งครูและเซิร์ฟเวอร์</span></div><div className="builder-actions"><button type="button" onClick={()=>moveQuestion(-1)} disabled={active===0} aria-label="เลื่อนข้อขึ้น"><ArrowUp/></button><button type="button" onClick={()=>moveQuestion(1)} disabled={active===questions.length-1} aria-label="เลื่อนข้อลง"><ArrowDown/></button><button type="button" onClick={removeQuestion} disabled={questions.length<=1} aria-label="ลบข้อนี้"><Trash2/></button></div></div><div className="builder-fields"><label>ชื่อโจทย์<input value={question.title} maxLength={60} onChange={event=>updateQuestion({title:event.target.value})} placeholder="เช่น แยกเหล็กจากผงถ่าน"/></label><label>สารที่ผสมกัน<input value={question.mixture} maxLength={120} onChange={event=>updateQuestion({mixture:event.target.value})} placeholder="ผงถ่าน + ผงตะไบเหล็ก"/></label><label>ภารกิจที่นักเรียนต้องทำ<textarea value={question.objective} maxLength={180} onChange={event=>updateQuestion({objective:event.target.value})} placeholder="แยกสารทั้งสองให้ได้"/></label></div><div className="builder-score"><label>คะแนนเต็ม<input type="number" min={1} max={100} value={question.maxPoints} onChange={event=>updateQuestion({maxPoints:Number(event.target.value)})}/></label><label>ตอบถูกได้<input type="number" min={1} max={question.maxPoints} value={question.correctPoints} onChange={event=>updateQuestion({correctPoints:Number(event.target.value)})}/></label><label>ตอบผิดลด<input type="number" min={0} max={20} value={question.wrongPenalty} onChange={event=>updateQuestion({wrongPenalty:Number(event.target.value)})}/></label></div><div className="builder-tools"><div className="section-title"><div><h3>ตัวเลือกอุปกรณ์ / ขั้นตอน</h3><span>เพิ่มทั้งวิธีที่ถูกและตัวลวงให้นักเรียนเลือก</span></div><button type="button" onClick={addTool} disabled={question.equipment.length>=10}><CirclePlus/>เพิ่มอุปกรณ์</button></div>{question.equipment.map((tool,index)=><div className="builder-tool-row" key={tool.id}><span>{index+1}</span><input value={tool.label} maxLength={80} onChange={event=>updateQuestion({equipment:question.equipment.map(item=>item.id===tool.id?{...item,label:event.target.value}:item)})} placeholder="ชื่ออุปกรณ์หรือขั้นตอน" aria-label={`อุปกรณ์ ${index+1}`}/><button type="button" onClick={()=>removeTool(tool.id)} disabled={question.equipment.length<=2} aria-label={`ลบอุปกรณ์ ${index+1}`}><Trash2/></button></div>)}</div><div className="builder-answer"><h3>ลำดับคำตอบที่ถูก</h3><p>แตะอุปกรณ์ด้านล่างตามลำดับที่ต้องใช้ นักเรียนจะไม่เห็นส่วนนี้</p><div className="builder-answer-sequence">{key.steps.length?key.steps.map((id,index)=><button type="button" key={id} onClick={()=>toggleAnswer(id)}>{index+1}. {question.equipment.find(item=>item.id===id)?.label||id} ×</button>):<span>ยังไม่ได้เลือกลำดับเฉลย</span>}</div><div className="builder-answer-options">{question.equipment.filter(item=>!key.steps.includes(item.id)).map(item=><button type="button" key={item.id} onClick={()=>toggleAnswer(item.id)} disabled={!item.label.trim()}>+ {item.label||"ตั้งชื่ออุปกรณ์ก่อน"}</button>)}</div></div><div className="builder-fields"><label>คำใบ้ของข้อนี้<textarea value={key.hint} maxLength={200} onChange={event=>updateKey({hint:event.target.value})} placeholder="ชวนคิดโดยไม่เฉลยตรง ๆ"/></label><label>คำอธิบายหลังตอบถูก<textarea value={key.explanation} maxLength={300} onChange={event=>updateKey({explanation:event.target.value})} placeholder="อธิบายหลักการแยกสารที่ใช้"/></label></div></section></div>{error&&<div className="error-box" role="alert">{error}</div>}<div className="builder-save"><button type="button" className="secondary-button" onClick={()=>router.push(`/teacher/classrooms/${room.id}`)}>ยกเลิก</button><button className="primary-button" type="submit" disabled={busy||!keysReady||room.status!=="OPEN"}>{busy?"กำลังบันทึก…":keysReady?"บันทึกเกมของฉัน":"กำลังโหลดเฉลย…"}</button></div></form></main></AppShell>;
}
